legalDataPrivacyText1: "FinBundle Pro è concepito come un'applicazione locale (\"Local-First\"). I tuoi dati finanziari sensibili, le transazioni e le strutture del portafoglio sono archiviati esclusivamente a livello locale sul tuo dispositivo (o nel file che scegli) e non vengono trasmessi ai server centrali dello sviluppatore.",
legalLiveRatesNote: "Nota sui tassi in tempo reale:",
legalDataPrivacyText2: "Per recuperare i tassi di cambio e i dati di mercato attuali, il software stabilisce connessioni dirette con fornitori di terze parti (ad es. Frankfurter API, Alpha Vantage, EODHD). Per motivi tecnici, il tuo indirizzo IP e il codice valuta/ticker richiesto vengono trasmessi a questi server durante queste richieste.",
legalMarketDataTitle: "Dati di mercato e fonti",
legalMarketDataText: "I tassi di mercato e di cambio forniti provengono da fornitori di terze parti, possono essere ritardati e sono solo a scopo informativo. Non sono adatti come base affidabile per decisioni di trading attive. Lo sviluppatore non si assume alcuna responsabilità per la disponibilità, l'accuratezza o la tempestività dei dati dell'API.",
legalImprintTitle: "Impressum / Contatti",
legalImprintTextName: "Thomas Kerle",
legalImprintTextStreet: "Schlossmatten 15",
legalImprintTextCity: "3150 Schwarzenburg",
legalImprintTextCountry: "Svizzera",
legalImprintTextEmail: "E-Mail: thomkerle@gmail.com",

